@@ -0,0 +1,9 @@
+import { sortEventCards } from './agenda.js';
+import { summarizeAttendance } from './attendance.js';
+
+export function buildOrganizerDigest(events, signupsByEvent) {
+  return sortEventCards(events).map(({ event, card }) => {
+    const signups = Object.hasOwn(signupsByEvent, card.id) ? signupsByEvent[card.id] : [];
+    return { ...card, ...summarizeAttendance(event, signups) };
+  });
+}

